"""Bina0.4Koochik reference OCR with pixel-derived layout and raw decoding traces."""
import argparse,copy,hashlib,json,pathlib,time
import torch
from PIL import Image
from transformers import AutoModel,AutoProcessor,GenerationConfig
from layout_regions import regions
from decoding import generate_repaired
R=pathlib.Path(__file__).resolve().parent

def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--image',required=True);p.add_argument('--output',required=True);p.add_argument('--device',choices=['auto','cpu','cuda'],default='auto');p.add_argument('--task',choices=['ocr','markup'],default='ocr');p.add_argument('--policy',choices=['layout-v2','original'],default='layout-v2');a=p.parse_args();torch.set_num_threads(4);torch.set_grad_enabled(False);device='cuda' if a.device=='auto' and torch.cuda.is_available() else 'cpu' if a.device=='auto' else a.device;dtype=torch.bfloat16 if device=='cuda' else torch.float32;tick=time.monotonic();model=AutoModel.from_pretrained(R,trust_remote_code=True,local_files_only=True,dtype=dtype).eval().to(device);processor=AutoProcessor.from_pretrained(R,trust_remote_code=True,local_files_only=True);config=GenerationConfig.from_pretrained(R,local_files_only=True);config.max_new_tokens=2048;assert not config.do_sample and config.num_beams==1 and config.repetition_penalty==1.1;loaded=time.monotonic()-tick;image=Image.open(a.image).convert('RGB');plan=regions(image) if a.policy=='layout-v2' else {'regions':[{'index':0,'bbox':[0,0,image.width,image.height]}]};prompt='</s><s><output_markdown><predict_text_in_pic>' if a.task=='markup' else '</s><s><predict_text_in_pic>';records=[];tick=time.monotonic()
 for region in plan['regions']:records.append({'region':region,**generate_repaired(model,processor,image.crop(tuple(region['bbox'])),prompt,copy.deepcopy(config))})
 result={'source_step':18404,'model':'Bina0.4Koochik','runtime':device,'dtype':str(dtype),'parameters':sum(p.numel() for p in model.parameters()),'image_sha256':hashlib.sha256(pathlib.Path(a.image).read_bytes()).hexdigest(),'policy':a.policy,'layout_plan':plan,'task':a.task,'ocr_prediction':'\n'.join(r['selected']['ocr_prediction'] for r in records if r['selected']['ocr_prediction']),'records':records,'load_seconds':loaded,'inference_seconds':time.monotonic()-tick,'capped_regions':sum(r['selected']['capped'] for r in records),'flagged_regions':sum(r['selected']['signal']['flagged'] for r in records),'natural_EOS_regions':sum(r['selected']['ended_with_eos'] and not r['selected']['capped'] for r in records),'repetition_guard_enabled':False,'no_repeat_constraint':False,'main_training_changes':False};out=pathlib.Path(a.output);out.parent.mkdir(parents=True,exist_ok=True);temp=out.with_suffix(out.suffix+'.partial');temp.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');temp.replace(out);print(result['ocr_prediction'])
